CREATE TABLE IF NOT EXISTS sessions (id SERIAL PRIMARY KEY, title TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS students (id SERIAL PRIMARY KEY, session_id INT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, name TEXT NOT NULL, picked BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS attempts (id SERIAL PRIMARY KEY, session_id INT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, student_id INT NOT NULL REFERENCES students(id) ON DELETE CASCADE, result TEXT NOT NULL CHECK (result IN ('no','partially','yes')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
